export const whimsicalCss = "/* Whimsical — converged site + chat theme.\n * Warm, playful, pastel pink/purple gradients. Nunito.\n * Light = pastel paper, dark = deep neon-pop violet.\n */\n\n@import url('https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap');\n\n/* === Tokens (light = default, dark = override) === */\n\n:root {\n  /* Site color tokens — light */\n  --color-surface: #fff5fb;\n  --color-surface-raised: #ffe8f3;\n  --color-surface-hover: #ffd9eb;\n  --color-border: #f1c2dd;\n  --color-border-subtle: #fadcec;\n\n  --color-text-primary: #4a2040;\n  --color-text-secondary: #7b5ea7;\n  --color-text-dim: #b18ad1;\n\n  --color-accent: #c0547a;\n  --color-accent-dim: rgba(192, 84, 122, 0.12);\n  --color-success: #6db26b;\n  --color-error: #d54a4a;\n  --color-info: #7b9fd9;\n\n  /* Chat color tokens — light */\n  --pc-surface: rgba(255, 255, 255, 0.7);\n  --pc-persona-bg: linear-gradient(135deg, #ff9a9e 0%, #fecfef 100%);\n  --pc-persona-text: #4a2040;\n  --pc-persona-name: #c0547a;\n  --pc-user-bg: linear-gradient(135deg, #a18cd1 0%, #c4b0e8 100%);\n  --pc-user-text: #2d1b4e;\n  --pc-user-name: #7b5ea7;\n  --pc-input-bg: #ffffff;\n  --pc-input-border: #e8d5f0;\n  --pc-input-focus: #d4a0d0;\n  --pc-send-bg: linear-gradient(135deg, #ff9a9e, #c4a0e8);\n  --pc-send-text: #ffffff;\n  --pc-time-color: rgba(0, 0, 0, 0.35);\n  --pc-avatar-persona-bg: #ffecd2;\n  --pc-avatar-user-bg: #e0d4f5;\n  --pc-shadow-tint: rgba(200, 140, 180, 0.2);\n  --pc-input-bg-area: rgba(255, 255, 255, 0.5);\n  --pc-input-border-area: rgba(200, 140, 180, 0.15);\n  --pc-popover-bg: rgba(255, 255, 255, 0.9);\n\n  /* Code highlighting (Shiki) — light */\n  --scp-shiki-theme: 'github-light';\n\n  /* Shared (non-color) tokens */\n  --font-display: 'Nunito', system-ui, sans-serif;\n  --font-mono: 'JetBrains Mono', ui-monospace, monospace;\n  --font-sans: 'Nunito', system-ui, sans-serif;\n  --pc-font: 'Nunito', sans-serif;\n  --pc-radius: 20px;\n}\n\n:root.dark {\n  /* Site color overrides — dark */\n  --color-surface: #1a1024;\n  --color-surface-raised: #2a1a3a;\n  --color-surface-hover: #3a2848;\n  --color-border: #4a3858;\n  --color-border-subtle: #322244;\n\n  --color-text-primary: #f5e8f5;\n  --color-text-secondary: #c0a8d8;\n  --color-text-dim: #8a72a8;\n\n  --color-accent: #f08aa8;\n  --color-accent-dim: rgba(240, 138, 168, 0.15);\n  --color-success: #7fc97a;\n  --color-error: #e87878;\n  --color-info: #a8b0e0;\n\n  /* Chat color overrides — dark */\n  --pc-surface: rgba(26, 16, 36, 0.7);\n  --pc-persona-bg: linear-gradient(135deg, #c8506a 0%, #d878a0 100%);\n  --pc-persona-text: #ffffff;\n  --pc-persona-name: #f8c0d0;\n  --pc-user-bg: linear-gradient(135deg, #5a4a98 0%, #7868b8 100%);\n  --pc-user-text: #ffffff;\n  --pc-user-name: #c8b0e0;\n  --pc-input-bg: rgba(26, 16, 36, 0.5);\n  --pc-input-border: #4a3858;\n  --pc-input-focus: #a878c8;\n  --pc-send-bg: linear-gradient(135deg, #c8506a, #7868b8);\n  --pc-send-text: #ffffff;\n  --pc-time-color: rgba(255, 255, 255, 0.4);\n  --pc-avatar-persona-bg: #3a1a2e;\n  --pc-avatar-user-bg: #2a1f48;\n  --pc-shadow-tint: rgba(240, 138, 168, 0.15);\n  --pc-input-bg-area: rgba(26, 16, 36, 0.5);\n  --pc-input-border-area: rgba(240, 138, 168, 0.10);\n  --pc-popover-bg: rgba(42, 26, 58, 0.92);\n\n  --scp-shiki-theme: 'github-dark';\n}\n\n/* === Site surface === */\n\nbody {\n  background: linear-gradient(180deg, var(--color-surface) 0%, var(--color-surface-raised) 100%);\n  color: var(--color-text-primary);\n  font-family: var(--font-sans);\n  font-size: 16px;\n  line-height: 1.7;\n  -webkit-font-smoothing: antialiased;\n}\n\n::selection { background: var(--color-accent); color: #ffffff; }\n\n.prose {\n  --tw-prose-body: var(--color-text-primary);\n  --tw-prose-headings: var(--color-accent);\n  --tw-prose-links: var(--color-accent);\n  --tw-prose-bold: var(--color-text-primary);\n  --tw-prose-code: var(--color-accent);\n  --tw-prose-pre-bg: var(--color-surface-raised);\n  --tw-prose-pre-code: var(--color-text-primary);\n  --tw-prose-counters: var(--color-text-secondary);\n  --tw-prose-bullets: var(--color-text-dim);\n  --tw-prose-hr: var(--color-border);\n  --tw-prose-quotes: var(--color-text-secondary);\n  --tw-prose-quote-borders: var(--color-accent);\n  --tw-prose-th-borders: var(--color-border);\n  --tw-prose-td-borders: var(--color-border-subtle);\n  --tw-prose-captions: var(--color-text-dim);\n}\n\n.prose :where(h1, h2, h3, h4):not(:where([class~='not-prose'], [class~='not-prose'] *)) {\n  font-family: var(--font-sans);\n  font-weight: 800;\n  letter-spacing: -0.01em;\n}\n.prose :where(a):not(:where([class~='not-prose'], [class~='not-prose'] *)) {\n  text-decoration: none;\n  color: var(--color-accent);\n  border-bottom: 2px solid var(--color-accent-dim);\n}\n.prose :where(a):not(:where([class~='not-prose'], [class~='not-prose'] *)):hover {\n  border-bottom-color: var(--color-accent);\n}\n.prose :where(code):not(:where(pre *, [class~='not-prose'], [class~='not-prose'] *)) {\n  font-family: var(--font-mono);\n  font-size: 0.85em;\n  background: var(--color-surface-raised);\n  padding: 0.15em 0.4em;\n  border-radius: 6px;\n}\n.prose :where(pre):not(:where([class~='not-prose'], [class~='not-prose'] *)) {\n  border: 1px solid var(--color-border-subtle);\n  border-radius: 14px;\n}\n\n/* === Chat surface === */\n\n.persona-chat {\n  font-family: var(--pc-font);\n  background: var(--pc-surface);\n  backdrop-filter: blur(10px);\n  border-radius: 28px;\n  box-shadow:\n    0 8px 32px var(--pc-shadow-tint),\n    0 2px 8px var(--pc-shadow-tint);\n}\n\n.persona-chat .pc-transcript::-webkit-scrollbar { width: 6px; }\n.persona-chat .pc-transcript::-webkit-scrollbar-track { background: transparent; }\n.persona-chat .pc-transcript::-webkit-scrollbar-thumb {\n  background: var(--pc-shadow-tint);\n  border-radius: 3px;\n}\n\n.persona-chat .pc-message {\n  animation: pc-pop-in 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);\n}\n\n@keyframes pc-pop-in {\n  from { opacity: 0; transform: translateY(10px) scale(0.95); }\n  to { opacity: 1; transform: translateY(0) scale(1); }\n}\n\n.persona-chat .pc-avatar {\n  width: 36px;\n  height: 36px;\n  border-radius: 50%;\n  font-size: 18px;\n}\n\n.persona-chat .pc-persona .pc-avatar { background: var(--pc-avatar-persona-bg); }\n.persona-chat .pc-user .pc-avatar { background: var(--pc-avatar-user-bg); }\n\n.persona-chat .pc-bubble {\n  padding: 12px 16px;\n  border-radius: var(--pc-radius);\n  line-height: 1.5;\n  font-size: 15px;\n}\n\n.persona-chat .pc-persona .pc-bubble {\n  background: var(--pc-persona-bg);\n  color: var(--pc-persona-text);\n  border-bottom-left-radius: 6px;\n}\n\n.persona-chat .pc-user .pc-bubble {\n  background: var(--pc-user-bg);\n  color: var(--pc-user-text);\n  border-bottom-right-radius: 6px;\n}\n\n.persona-chat .pc-sender {\n  font-size: 12px;\n  font-weight: 700;\n  margin-bottom: 3px;\n}\n\n.persona-chat .pc-persona .pc-sender { color: var(--pc-persona-name); }\n.persona-chat .pc-user .pc-sender { color: var(--pc-user-name); }\n\n.persona-chat .pc-time {\n  font-size: 10px;\n  color: var(--pc-time-color);\n  margin-top: 4px;\n}\n\n.persona-chat .pc-dots span {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background: var(--pc-persona-name);\n  opacity: 0.4;\n  animation: pc-bounce 1.4s ease-in-out infinite;\n}\n\n.persona-chat .pc-dots span:nth-child(2) { animation-delay: 0.2s; }\n.persona-chat .pc-dots span:nth-child(3) { animation-delay: 0.4s; }\n\n@keyframes pc-bounce {\n  0%, 80%, 100% { transform: translateY(0); opacity: 0.4; }\n  40% { transform: translateY(-8px); opacity: 1; }\n}\n\n.persona-chat .pc-input-area {\n  background: var(--pc-input-bg-area);\n  border-top: 1px solid var(--pc-input-border-area);\n}\n\n.persona-chat .pc-input {\n  padding: 12px 18px;\n  border: 2px solid var(--pc-input-border);\n  border-radius: 24px;\n  font-family: var(--pc-font);\n  font-size: 15px;\n  background: var(--pc-input-bg);\n  color: var(--color-text-primary);\n}\n\n.persona-chat .pc-input:focus { border-color: var(--pc-input-focus); }\n.persona-chat .pc-input::placeholder { color: var(--color-text-dim); }\n\n.persona-chat .pc-send-btn {\n  width: 46px;\n  height: 46px;\n  border: none;\n  border-radius: 50%;\n  background: var(--pc-send-bg);\n  color: var(--pc-send-text);\n}\n\n.persona-chat .pc-send-btn:hover { transform: scale(1.08); }\n.persona-chat .pc-send-btn:active { transform: scale(0.95); }\n.persona-chat .pc-send-btn:disabled { opacity: 0.5; transform: none; }\n\n/* Rich content */\n.persona-chat .pc-content-link {\n  color: var(--pc-persona-name);\n  text-decoration: underline;\n  text-underline-offset: 2px;\n  font-size: 14px;\n}\n.persona-chat .pc-content-link:hover { opacity: 0.7; }\n.persona-chat .pc-content-image {\n  border-radius: 12px;\n}\n\n/* Popover */\n.persona-chat .pc-popover {\n  background: var(--pc-popover-bg);\n  backdrop-filter: blur(12px);\n  border: 2px solid var(--pc-input-border);\n  border-radius: 20px;\n  padding: 16px;\n  box-shadow: 0 8px 24px var(--pc-shadow-tint);\n}\n.persona-chat .pc-popover-title {\n  font-size: 15px;\n  font-weight: 700;\n  color: var(--pc-persona-name);\n}\n.persona-chat .pc-popover-desc {\n  font-size: 14px;\n  color: var(--color-text-primary);\n  line-height: 1.5;\n}\n.persona-chat .pc-popover-link {\n  color: var(--pc-persona-name);\n  text-decoration: none;\n  font-size: 14px;\n  padding: 4px 0;\n  display: block;\n}\n.persona-chat .pc-popover-link:hover { text-decoration: underline; }\n.persona-chat .pc-popover-toggle { color: var(--pc-persona-name); }\n.persona-chat .pc-popover-toggle:hover { opacity: 0.8; }\n.persona-chat .pc-popover-arrow { border-top-color: var(--pc-persona-name); }\n"
